package net.civeira.phylax.features.document.template.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.document.template.domain.TemplateChannelOptions;

class ChannelVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property channel of template ")
  void test_channel_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ChannelVO.tryFrom("_MAIL_"));
    Assertions.assertEquals(TemplateChannelOptions.MAIL, ChannelVO.tryFrom("MAIL").getChannel());
    Assertions.assertThrows(ConstraintException.class, () -> ChannelVO.tryFrom(null));
    Assertions.assertEquals(TemplateChannelOptions.MAIL,
        ChannelVO.from(TemplateChannelOptions.MAIL).getChannel());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ChannelVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + TemplateChannelOptions.MAIL + "]",
        ChannelVO.from(TemplateChannelOptions.MAIL).toString());
  }
}
